SELECT     CONCAT(CAST(SUBSTRING(CAST(tjzq AS VARCHAR(20)), 5, 1) AS INT), '月') AS month,     ROUND(SUM(CASE         WHEN SUBSTRING(CAST(tjzq AS VARCHAR(20)), 1, 4) = #{ssnd}         THEN djtqje         ELSE 0     END) / 100000000, 2) AS bntqje,     ROUND(SUM(CASE         WHEN SUBSTRING(CAST(tjzq AS VARCHAR(20)), 1, 4) = CAST(#{ssnd} AS INT) - 1         THEN djtqje         ELSE 0     END) / 100000000, 2) AS sntqje FROM dws_bus_ft_per_qfq WHERE SUBSTRING(CAST(tjzq AS VARCHAR(20)), 1, 4) IN (#{ssnd}, CAST(#{ssnd} AS INT) - 1) GROUP BY SUBSTRING(CAST(tjzq AS VARCHAR(20)), 5, 1) ORDER BY month
